"12-9":[["このケーキは甘[あま]いです。","This cake is sweet."],["甘[あま]い物[もの]が好[す]きです。","I like sweet things."]],
"12-10":[["このカレーは辛[から]いです。","This curry is spicy."],["辛[から]い料理[りょうり]は好[す]きですか。","Do you like spicy food?"]],
"12-11":[["このかばんは重[おも]いです。","This bag is heavy."],["荷物[にもつ]が重[おも]いです。","The luggage is heavy."]],
"12-12":[["このパソコンは軽[かる]いです。","This computer is light."],["軽[かる]いかばんが欲[ほ]しいです。","I want a light bag."]],
"12-13":[["どの季節[きせつ]が好[す]きですか。","Which season do you like?"],["日本[にほん]には四[よっ]つの季節[きせつ]があります。","Japan has four seasons."]],
"12-14":[["春[はる]は桜[さくら]がきれいです。","The cherry blossoms are beautiful in spring."],["わたしは春[はる]がいちばん好[す]きです。","I like spring the most."]],
