"12-16":[["秋[あき]は涼[すず]しいです。","Autumn is cool."],["秋[あき]の山[やま]はきれいです。","The mountains are beautiful in autumn."]],
"12-17":[["冬[ふゆ]は寒[さむ]いです。","Winter is cold."],["冬[ふゆ]にスキーをします。","I go skiing in winter."]],
"12-18":[["きょうはいい天気[てんき]ですね。","Nice weather today, isn't it?"],["あしたの天気[てんき]はどうですか。","What will the weather be like tomorrow?"]],
"12-19":[["きょうは雨[あめ]です。","It's raining today."],["雨[あめ]の日[ひ]は傘[かさ]を持[も]っていきます。","I take an umbrella on rainy days."]],
"12-20":[["北海道[ほっかいどう]は雪[ゆき]が多[おお]いです。","Hokkaido gets a lot of snow."],["雪[ゆき]は白[しろ]いです。","Snow is white."]],
"12-21":[["きょうは曇[くも]りです。","It's cloudy today."],["あしたは曇[くも]りでしょう。","It will probably be cloudy tomorrow."]],
"12-22":[["駅[えき]の前[まえ]にホテルがあります。","There is a hotel in front of the station."],["このホテルは高[たか]いです。","This hotel is expensive."]],
"12-23":[["空港[くうこう]までバスで行[い]きます。","I go to the airport by bus."],["空港[くうこう]で友達[ともだち]を迎[むか]えます。","I meet my friend at the airport."]],
"12-24":[["夏[なつ]は海[うみ]で泳[およ]ぎます。","I swim in the sea in summer."],["海[うみ]はとてもきれいです。","The sea is very beautiful."]],
"12-25":[["世界[せかい]でいちばん高[たか]い山[やま]はどこですか。","Which is the highest mountain in the world?"],["世界[せかい]を旅行[りょこう]したいです。","I want to travel the world."]],
"12-26":[["土曜日[どようび]にパーティーがあります。","There's a party on Saturday."],["パーティーは楽[たの]しかったです。","The party was fun."]],
"12-27":[["京都[きょうと]の祭[まつ]りは有名[ゆうめい]です。","Kyoto's festivals are famous."],["夏[なつ]に祭[まつ]りへ行[い]きました。","I went to a festival in summer."]],
"12-28":[["とり肉[にく]が好[す]きです。","I like chicken."],["スーパーでとり肉[にく]を買[か]います。","I buy chicken at the supermarket."]],
"12-29":[["牛肉[ぎゅうにく]は高[たか]いです。","Beef is expensive."],["牛肉[ぎゅうにく]と豚肉[ぶたにく]とどちらが好[す]きですか。","Which do you like better, beef or pork?"]],
"12-30":[["豚肉[ぶたにく]は牛肉[ぎゅうにく]より安[やす]いです。","Pork is cheaper than beef."],["晩[ばん]ごはんに豚肉[ぶたにく]を食[た]べました。","I ate pork for dinner."]],
"12-31":[["コーヒーと紅茶[こうちゃ]とどちらがいいですか。","Which would you like, coffee or tea?"],["夏[なつ]と冬[ふゆ]とどちらが好[す]きですか。","Which do you like better, summer or winter?"]],
"12-32":[["スポーツでサッカーがいちばん好[す]きです。","Of all sports, I like soccer the most."],["日本[にほん]でいちばん高[たか]い山[やま]は富士山[ふじさん]です。","The highest mountain in Japan is Mt. Fuji."]],
"12-33":[["東京[とうきょう]は大阪[おおさか]よりずっと大[おお]きいです。","Tokyo is much bigger than Osaka."],["新幹線[しんかんせん]はバスよりずっと速[はや]いです。","The bullet train is far faster than the bus."]],
"12-34":[["初[はじ]めて日本[にほん]へ来[き]ました。","I came to Japan for the first time."],["初[はじ]めてすしを食[た]べました。","I ate sushi for the first time."]],
"12-35":[["ただいま。","I'm home."],["「ただいま。」「お帰[かえ]りなさい。」","\"I'm home.\" \"Welcome home.\""]],
"12-36":[["「ただいま。」「お帰[かえ]りなさい。」","\"I'm home.\" \"Welcome home.\""],["お帰[かえ]りなさい。旅行[りょこう]はどうでしたか。","Welcome home. How was your trip?"]],
"12-37":[["きょうはたくさん歩[ある]きました。疲[つか]れました。","I walked a lot today. I'm tired."],["仕事[しごと]が忙[いそが]しくて、疲[つか]れました。","Work was busy, and I'm tired."]],
"13-0":[["子[こ]どもは公園[こうえん]で遊[あそ]びます。","Children play in the park."],["日曜日[にちようび]に友達[ともだち]と遊[あそ]びました。","I hung out with friends on Sunday."]],
"13-1":[["夏[なつ]は海[うみ]で泳[およ]ぎます。","I swim in the sea in summer."],["プールで泳[およ]ぎたいです。","I want to swim in the pool."]],
"13-2":[["空港[くうこう]へ友達[ともだち]を迎[むか]えに行[い]きます。","I'm going to the airport to meet my friend."],["駅[えき]で母[はは]を迎[むか]えます。","I meet my mother at the station."]],
"13-3":[["姉[あね]は来月[らいげつ]結婚[けっこん]します。","My older sister is getting married next month."],["いつ結婚[けっこん]しましたか。","When did you get married?"]],
"13-4":[["デパートで買[か]い物[もの]します。","I go shopping at the department store."],["週末[しゅうまつ]は買[か]い物[もの]しました。","I went shopping on the weekend."]],
"13-5":[["レストランで食事[しょくじ]します。","I have a meal at a restaurant."],["いっしょに食事[しょくじ]しませんか。","Would you like to have a meal together?"]],
"13-6":[["毎朝[まいあさ]公園[こうえん]を散歩[さんぽ]します。","I take a walk in the park every morning."],["犬[いぬ]と散歩[さんぽ]します。","I walk with my dog."]],
"13-7":[["仕事[しごと]は大変[たいへん]です。","The work is hard."],["毎日[まいにち]漢字[かんじ]を覚[おぼ]えるのは大変[たいへん]です。","Memorising kanji every day is tough."]],
"13-8":[["新[あたら]しいパソコンが欲[ほ]しいです。","I want a new computer."],["誕生日[たんじょうび]に何[なに]が欲[ほ]しいですか。","What do you want for your birthday?"]],
"13-9":[["わたしの部屋[へや]は広[ひろ]いです。","My room is spacious."],["この公園[こうえん]はとても広[ひろ]いです。","This park is very big."]],
