"13-11":[["プールで泳[およ]ぎます。","I swim in the pool."],["夏[なつ]はプールへ行[い]きます。","I go to the pool in summer."]],
"13-12":[["川[かわ]で魚[さかな]を釣[つ]ります。","I fish in the river."],["この川[かわ]はきれいです。","This river is clean."]],
"13-13":[["父[ちち]は釣[つ]りが好[す]きです。","My father likes fishing."],["週末[しゅうまつ]、川[かわ]へ釣[つ]りに行[い]きます。","I'm going fishing at the river this weekend."]],
"13-14":[["冬[ふゆ]に北海道[ほっかいどう]でスキーをします。","I ski in Hokkaido in winter."],["スキーが上手[じょうず]ですね。","You're good at skiing."]],
"13-15":[["週末[しゅうまつ]は何[なに]をしますか。","What do you do on weekends?"],["週末[しゅうまつ]は家族[かぞく]と過[す]ごします。","I spend weekends with my family."]],
"13-16":[["正月[しょうがつ]は家族[かぞく]と過[す]ごします。","I spend New Year with my family."],["お正月[しょうがつ]に神社[じんじゃ]へ行[い]きます。","I go to a shrine at New Year."]],
"13-17":[["7時[しちじ]ごろ起[お]きます。","I get up around 7."],["3時[さんじ]ごろ駅[えき]に着[つ]きます。","I'll arrive at the station around 3."]],
"13-18":[["何[なに]か飲[の]みませんか。","Would you like something to drink?"],["何[なに]か食[た]べたいです。","I want to eat something."]],
"13-19":[["週末[しゅうまつ]どこか行[い]きましたか。","Did you go anywhere on the weekend?"],["どこかで昼[ひる]ごはんを食[た]べましょう。","Let's eat lunch somewhere."]],
"13-20":[["のどがかわきました。水[みず]をください。","I'm thirsty. Water, please."],["たくさん歩[ある]いて、のどがかわきました。","I walked a lot and got thirsty."]],
