"22-9":[["帽子[ぼうし]をかぶっています。","I'm wearing a hat."],["赤[あか]い帽子[ぼうし]の子[こ]は妹[いもうと]です。","The child in the red hat is my younger sister."]],
"22-10":[["めがねをかけています。","I wear glasses."],["新[あたら]しい眼鏡[めがね]を買[か]いました。","I bought new glasses."]],
"22-11":[["誕生日[たんじょうび]にケーキを食[た]べます。","I eat cake on my birthday."],["母[はは]が作[つく]ったケーキです。","This is a cake my mother made."]],
"22-12":[["毎日[まいにち]弁当[べんとう]を作[つく]ります。","I make a packed lunch every day."],["コンビニで弁当[べんとう]を買[か]いました。","I bought a box lunch at the convenience store."]],
