"22-17":[["和室[わしつ]に布団[ふとん]を敷[し]いて寝[ね]ます。","I lay out a futon and sleep in the Japanese-style room."],["このアパートには和室[わしつ]があります。","This apartment has a Japanese-style room."]],
"22-18":[["布団[ふとん]で寝[ね]ます。","I sleep on a futon."],["天気[てんき]がいいですから、布団[ふとん]を干[ほ]します。","The weather's nice, so I'll air the futon."]],
"23-0":[["わからないときは、先生[せんせい]に聞[き]きます。","When I don't understand, I ask the teacher."],["駅[えき]への道[みち]を聞[き]きました。","I asked the way to the station."]],
"23-1":[["このつまみを右[みぎ]へ回[まわ]すと、音[おと]が大[おお]きくなります。","If you turn this knob to the right, the sound gets louder."],["ドアのノブを回[まわ]してください。","Please turn the doorknob."]],
"23-2":[["このドアは引[ひ]いて開[あ]けます。","You pull this door to open it."],["ひもを引[ひ]くと、電気[でんき]がつきます。","If you pull the cord, the light comes on."]],
"23-3":[["髪[かみ]の色[いろ]を変[か]えました。","I changed my hair colour."],["予定[よてい]を変[か]えてもいいですか。","May I change the plan?"]],
"23-4":[["この絵[え]に触[さわ]らないでください。","Please don't touch this painting."],["猫[ねこ]に触[さわ]ってもいいですか。","May I touch the cat?"]],
"23-5":[["毎日[まいにち]30分[さんじゅっぷん]歩[ある]きます。","I walk for 30 minutes every day."],["駅[えき]まで歩[ある]きましょう。","Let's walk to the station."]],
"23-6":[["この橋[はし]を渡[わた]ると、駅[えき]があります。","If you cross this bridge, there's the station."],["道[みち]を渡[わた]るとき、車[くるま]に気[き]をつけてください。","Watch out for cars when you cross the road."]],
