"23-16":[["あの角[かど]にコンビニがあります。","There's a convenience store on that corner."],["次[つぎ]の角[かど]を右[みぎ]に曲[ま]がってください。","Please turn right at the next corner."]],
"23-17":[["この橋[はし]を渡[わた]ってください。","Please cross this bridge."],["橋[はし]の上[うえ]から川[かわ]を見[み]ます。","I look at the river from the bridge."]],
"23-18":[["駐車場[ちゅうしゃじょう]に車[くるま]を止[と]めます。","I park my car in the car park."],["スーパーの駐車場[ちゅうしゃじょう]は広[ひろ]いです。","The supermarket car park is big."]],
"23-19":[["あの白[しろ]い建物[たてもの]は病院[びょういん]です。","That white building is a hospital."],["京都[きょうと]には古[ふる]い建物[たてもの]が多[おお]いです。","Kyoto has many old buildings."]],
"23-20":[["この映画[えいが]は何回[なんかい]も見[み]ました。","I've seen this movie many times."],["何回[なんかい]も電話[でんわ]しました。","I called many times."]],
"24-0":[["友達[ともだち]がわたしに本[ほん]をくれました。","My friend gave me a book."],["母[はは]がセーターをくれました。","My mother gave me a sweater."]],
"24-1":[["自転車[じてんしゃ]を直[なお]してもらいました。","I had my bicycle repaired."],["先生[せんせい]に作文[さくぶん]を直[なお]してもらいました。","I had the teacher correct my essay."]],
"24-2":[["子[こ]どもを公園[こうえん]へ連[つ]れていきます。","I take the children to the park."],["犬[いぬ]を散歩[さんぽ]に連[つ]れていきます。","I take the dog for a walk."]],
"24-3":[["パーティーに友達[ともだち]を連[つ]れてきてもいいですか。","May I bring a friend to the party?"],["あした妹[いもうと]を連[つ]れてきます。","I'll bring my younger sister tomorrow."]],
"24-4":[["友達[ともだち]を家族[かぞく]に紹介[しょうかい]します。","I introduce my friend to my family."],["いいレストランを紹介[しょうかい]してください。","Please recommend a good restaurant."]],
