"24-7":[["おじいさんは80歳[はちじゅっさい]です。","Grandfather is 80."],["公園[こうえん]でおじいさんが散歩[さんぽ]しています。","An old man is walking in the park."]],
"24-8":[["おばあさんにセーターをもらいました。","I got a sweater from my grandmother."],["おばあさんの荷物[にもつ]を持[も]ってあげました。","I carried the old woman's bags for her."]],
