"25-5":[["これはいいチャンスです。","This is a good chance."],["チャンスがあったら、日本[にほん]で働[はたら]きたいです。","If I get the chance, I want to work in Japan."]],
"25-6":[["1億円[いちおくえん]あったら、何[なに]をしますか。","What would you do if you had 100 million yen?"],["日本[にほん]の人口[じんこう]は1億[いちおく]人[にん]ぐらいです。","Japan's population is about 100 million."]],
"25-7":[["もし雨[あめ]が降[ふ]ったら、行[い]きません。","If it rains, I won't go."],["もしお金[かね]があったら、旅行[りょこう]したいです。","If I had money, I'd like to travel."]],
"25-8":[["この言葉[ことば]の意味[いみ]がわかりません。","I don't know the meaning of this word."],["意味[いみ]を辞書[じしょ]で調[しら]べます。","I look up the meaning in a dictionary."]],
