"25-11":[["あしたの試験[しけん]、頑張[がんば]ります。","I'll do my best on tomorrow's exam."],["頑張[がんば]ってください。","Good luck! (Do your best.)"]],
"25-12":[["いろいろお世話[せわ]になりました。","Thank you for everything you've done for me."],["先生[せんせい]、一年間[いちねんかん]お世話[せわ]になりました。","Thank you for all your help this year, teacher."]],
"26-0":[["ちょっとこのパソコンを見[み]てくれませんか。","Could you take a look at this computer?"],["宿題[しゅくだい]を見[み]ていただけませんか。","Could you check my homework?"]],
"26-1":[["かぎを探[さが]しています。","I'm looking for my key."],["新[あたら]しいアパートを探[さが]しているんです。","I'm looking for a new apartment."]],
"26-2":[["電車[でんしゃ]が遅[おく]れました。","The train was late."],["すみません、会議[かいぎ]に遅[おく]れました。","Sorry, I was late for the meeting."]],
"26-3":[["急[いそ]げば、間[ま]に合[あ]いますよ。","If you hurry, you'll make it in time."],["9時[くじ]の電車[でんしゃ]に間[ま]に合[あ]いませんでした。","I didn't make the 9 o'clock train."]],
"26-4":[["宿題[しゅくだい]をやりましたか。","Did you do your homework?"],["週末[しゅうまつ]はサッカーをやります。","I play soccer on weekends."]],
