"26-10":[["夏[なつ]に盆踊[ぼんおど]りに行[い]きました。","I went to a Bon dance in summer."],["盆踊[ぼんおど]りの練習[れんしゅう]をしています。","I'm practising the Bon dance."]],
"26-11":[["日曜日[にちようび]に公園[こうえん]でフリーマーケットがあります。","There's a flea market in the park on Sunday."],["フリーマーケットで安[やす]い服[ふく]を買[か]いました。","I bought cheap clothes at the flea market."]],
"26-12":[["パーティーの場所[ばしょ]はどこですか。","Where is the party being held?"],["会議[かいぎ]の場所[ばしょ]が変[か]わりました。","The meeting place has changed."]],
"26-13":[["週末[しゅうまつ]はボランティアをしています。","I volunteer on weekends."],["ボランティアに参加[さんか]したいんですが。","I'd like to take part as a volunteer."]],
