"26-32":[["ごみ置[お]き場[ば]はどこですか。","Where is the rubbish collection point?"],["自転車[じてんしゃ]置[お]き場[ば]は駅[えき]の前[まえ]です。","The bicycle parking is in front of the station."]],
"26-33":[["駅[えき]の横[よこ]にコンビニがあります。","There's a convenience store beside the station."],["ベッドの横[よこ]に机[つくえ]があります。","There's a desk beside the bed."]],
"26-34":[["瓶[びん]はこの箱[はこ]に入[い]れてください。","Please put bottles in this box."],["瓶[びん]のごみは水曜日[すいようび]に出[だ]します。","I put out bottles on Wednesdays."]],
"26-35":[["缶[かん]と瓶[びん]は分[わ]けて出[だ]してください。","Please put out cans and bottles separately."],["缶[かん]のコーヒーを飲[の]みました。","I drank a can of coffee."]],
