"32-11":[["平日[へいじつ]の昼[ひる]は電車[でんしゃ]がすいています。","Trains are empty around midday on weekdays."],["夜[よる]になると、道[みち]がすきます。","The roads empty out at night."]],
"32-12":[["あしたのサッカーの試合[しあい]に出[で]ます。","I'll play in tomorrow's soccer match."],["パーティーに出[で]るつもりです。","I intend to go to the party."]],
"32-13":[["無理[むり]をしないでください。","Please don't overdo it."],["無理[むり]をして、病気[びょうき]になってしまいました。","I overdid it and got sick."]],
"32-14":[["時間[じかん]は十分[じゅうぶん]あります。","There's plenty of time."],["十分[じゅうぶん]休[やす]んだほうがいいですよ。","You should get enough rest."]],
"32-15":[["このパソコンはちょっとおかしいです。","This computer is a bit strange."],["その話[はなし]はおかしくて、みんな笑[わら]いました。","The story was so funny that everyone laughed."]],
"32-16":[["隣[となり]の部屋[へや]がうるさいです。","The next room is noisy."],["うるさいですから、窓[まど]を閉[し]めてください。","It's noisy, so please close the window."]],
"32-17":[["先生[せんせい]、熱[ねつ]があるんですが。","Doctor, I have a fever."],["病院[びょういん]の先生[せんせい]に薬[くすり]をもらいました。","I got medicine from the doctor at the hospital."]],
