"32-19":[["サッカーの試合[しあい]でけがをしました。","I got injured in a soccer match."],["けがをしないように、気[き]をつけてください。","Be careful not to get hurt."]],
"32-20":[["せきが止[と]まりません。","I can't stop coughing."],["せきが出[で]るときは、マスクをしたほうがいいです。","When you have a cough, you should wear a mask."]],
"32-21":[["インフルエンザで学校[がっこう]を休[やす]みました。","I missed school because of the flu."],["冬[ふゆ]はインフルエンザに気[き]をつけてください。","Watch out for influenza in winter."]],
"32-22":[["太陽[たいよう]が東[ひがし]から出[で]ます。","The sun rises in the east."],["きょうは太陽[たいよう]が強[つよ]いです。","The sun is strong today."]],
