"32-33":[["夕方[ゆうがた]から雨[あめ]になるでしょう。","It will probably start raining in the late afternoon."],["夕方[ゆうがた]、犬[いぬ]と散歩[さんぽ]します。","I walk the dog in the late afternoon."]],
"32-34":[["3年前[さんねんまえ]に日本[にほん]へ来[き]ました。","I came to Japan three years ago."],["前[まえ]にこの映画[えいが]を見[み]たことがあります。","I've seen this film before."]],
"32-35":[["きのうは遅[おそ]くまで仕事[しごと]をしました。","I worked late yesterday."],["夜[よる]遅[おそ]く電話[でんわ]しないでください。","Please don't phone late at night."]],
"32-36":[["こんなにたくさん食[た]べられません。","I can't eat this much."],["こんなに寒[さむ]い冬[ふゆ]は初[はじ]めてです。","This is the first time I've had such a cold winter."]],
