"32-39":[["母[はは]はいつも元気[げんき]です。","My mother is always full of energy."],["子[こ]どもたちの元気[げんき]な声[こえ]が聞[き]こえます。","I can hear the lively voices of the children."]],
"32-40":[["胃[い]が痛[いた]いです。","My stomach hurts."],["食[た]べすぎて、胃[い]の調子[ちょうし]が悪[わる]いです。","I ate too much and my stomach feels bad."]],
