"32-42":[["「かぜをひいたんです。」「それはいけませんね。」","\"I've caught a cold.\" \"I'm sorry to hear that.\""],["「頭[あたま]が痛[いた]いんです。」「それはいけませんね。」","\"I have a headache.\" \"That's too bad.\""]],
"32-43":[["毎朝[まいあさ]、星占[ほしうらな]いを見[み]ます。","I check my horoscope every morning."],["星占[ほしうらな]いによると、きょうはいい日[ひ]です。","According to my horoscope, today is a good day."]],
