"32-46":[["日本語[にほんご]がわからなくて、困[こま]りました。","I was in trouble because I didn't understand Japanese."],["財布[さいふ]を落[お]として、困[こま]っています。","I've lost my wallet and I'm in trouble."]],
"32-47":[["宝[たから]くじを買[か]いました。","I bought a lottery ticket."],["宝[たから]くじが当[あ]たったら、家[いえ]を買[か]いたいです。","If I win the lottery, I want to buy a house."]],
"32-48":[["宝[たから]くじが当[あ]たりました。","I won the lottery."],["あしたの天気[てんき]予報[よほう]は当[あ]たるでしょうか。","I wonder if tomorrow's weather forecast will be right."]],
"32-49":[["健康[けんこう]のために、毎日[まいにち]歩[ある]いています。","I walk every day for my health."],["たばこは健康[けんこう]に悪[わる]いです。","Smoking is bad for your health."]],
"32-50":[["このドラマは恋愛[れんあい]の話[はなし]です。","This drama is a love story."],["星占[ほしうらな]いによると、恋愛[れんあい]運[うん]がいいです。","According to my horoscope, my love luck is good."]],
