"41-48":[["船[ふね]が陸[りく]に着[つ]きました。","The ship reached land."],["かめは陸[りく]の上[うえ]をゆっくり歩[ある]きます。","Turtles walk slowly on land."]],
"41-49":[["箱[はこ]を開[あ]けると、白[しろ]い煙[けむり]が出[で]てきました。","When he opened the box, white smoke came out."],["台所[だいどころ]から煙[けむり]が出[で]ています。","Smoke is coming from the kitchen."]],
"41-50":[["浦島太郎[うらしまたろう]の髪[かみ]は真[ま]っ白[しろ]になりました。","Urashima Taro's hair turned pure white."],["雪[ゆき]で町[まち]が真[ま]っ白[しろ]です。","The town is pure white with snow."]],
