"42-24":[["缶切[かんき]りで缶[かん]を開[あ]けます。","I open the tin with a can opener."],["缶切[かんき]りがなくて困[こま]りました。","I was stuck without a can opener."]],
"42-25":[["非常時[ひじょうじ]のために、缶詰[かんづめ]を買[か]っておきます。","I buy canned food for emergencies."],["缶詰[かんづめ]の魚[さかな]を食[た]べました。","I ate canned fish."]],
