"50-9":[["会議[かいぎ]の資料[しりょう]を用意[ようい]しておきます。","I'll get the meeting materials ready."],["お客様[きゃくさま]のために飲[の]み物[もの]を用意[ようい]しました。","I prepared drinks for the guests."]],
"50-10":[["私[わたくし]がご案内[あんない]いたします。","I'll show you around."],["私[わたくし]は営業部[えいぎょうぶ]の田中[たなか]と申[もう]します。","I'm Tanaka from the sales department."]],
"50-11":[["京都[きょうと]でガイドに案内[あんない]してもらいました。","A guide showed us around Kyoto."],["将来[しょうらい]、観光[かんこう]ガイドになりたいです。","In the future I want to be a tour guide."]],
"50-12":[["メールアドレスを教[おし]えていただけませんか。","Could you tell me your email address?"],["新[あたら]しいメールアドレスをお知[し]らせします。","Let me tell you my new email address."]],
"50-13":[["旅行[りょこう]のスケジュールを確[たし]かめます。","I'll check the trip schedule."],["来週[らいしゅう]はスケジュールがいっぱいです。","My schedule is full next week."]],
"50-14":[["さ来週[らいしゅう]、国[くに]へ帰[かえ]ります。","I'm going back to my country the week after next."],["試験[しけん]はさ来週[らいしゅう]の月曜日[げつようび]です。","The exam is on Monday the week after next."]],
"50-15":[["さ来月[らいげつ]、引[ひ]っ越[こ]しします。","I'm moving the month after next."],["さ来月[らいげつ]に結婚[けっこん]します。","I'm getting married the month after next."]],
"50-16":[["さ来年[らいねん]、大学[だいがく]を卒業[そつぎょう]します。","I'll graduate from university the year after next."],["さ来年[らいねん]は日本[にほん]で働[はたら]きたいです。","The year after next, I want to work in Japan."]],
"50-17":[["初[はじ]めに、自己紹介[じこしょうかい]をお願[ねが]いします。","First, please introduce yourselves."],["初[はじ]めに、今日[きょう]の予定[よてい]を説明[せつめい]します。","First, I'll explain today's schedule."]],
