"50-19":[["スピーチ大会[たいかい]で賞金[しょうきん]をもらいました。","I won prize money at the speech contest."],["賞金[しょうきん]で旅行[りょこう]に行[い]きます。","I'll go on a trip with the prize money."]],
"50-20":[["動物園[どうぶつえん]できりんを見[み]ました。","I saw a giraffe at the zoo."],["きりんは首[くび]が長[なが]いです。","Giraffes have long necks."]],
"50-21":[["子[こ]どものころ、医者[いしゃ]になりたかったです。","When I was a child, I wanted to be a doctor."],["日本[にほん]へ来[き]たころは、日本語[にほんご]が全然[ぜんぜん]わかりませんでした。","When I first came to Japan, I didn't understand Japanese at all."]],
"50-22":[["やっと夢[ゆめ]がかないました。","My dream has finally come true."],["夢[ゆめ]がかなうように、頑張[がんば]ります。","I'll do my best so that my dream comes true."]],
"50-23":[["みんなが応援[おうえん]してくれました。","Everyone supported me."],["日本[にほん]のチームを応援[おうえん]しています。","I'm cheering for the Japanese team."]],
"50-24":[["心[こころ]から感謝[かんしゃ]しています。","I'm truly grateful."],["心[こころ]からお礼[れい]を申[もう]し上[あ]げます。","I sincerely thank you."]],
"50-25":[["皆様[みなさま]に感謝[かんしゃ]いたします。","I'm grateful to you all."],["両親[りょうしん]に感謝[かんしゃ]しています。","I'm thankful to my parents."]],
"50-26":[["お世話[せわ]になった先生[せんせい]にお礼[れい]の手紙[てがみ]を書[か]きました。","I wrote a thank-you letter to the teacher who helped me."],["お礼[れい]に、お菓子[かし]を持[も]ってきました。","I brought some sweets as thanks."]],
